// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // The deployer (this test contract) is the current owner; drive c through setOwner
        // from the owner, with the FUZZER-chosen proposed new owner. Keep the domain wide:
        // any address is admissible as the proposed new owner.
        vm.assume(newOwner != address(0));

        vm.prank(address(this)); // caller is the current owner, so the call must succeed
        bool ok = c.setOwner(newOwner);

        // General rule: after a successful setOwner(a) by the owner, c.owner() == a.
        assertTrue(ok && c.owner() == newOwner);
    }
}

