pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // c's owner is this test contract (deployer). Drive setOwner from the
        // CURRENT owner so the authorized path is exercised for any fuzzed target.
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.setOwner(newOwner);
        // Rule: after the owner transfers control to newOwner, c.owner() is
        // exactly newOwner, and control has actually MOVED to newOwner: the new
        // owner can now perform an owner-only action. The mutant overwrites
        // owner with the caller in the modifier before the assignment, so for
        // any newOwner != currentOwner the final owner/state diverges.
        assertTrue(c.owner() == newOwner && newOwner != currentOwner || c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address target) public {
        // wide domain: any non-zero actor distinct from the deployer (this test contract)
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(target != address(0));

        // step 1: current owner (address(this), the deployer) delegates ownership to the fuzzed actor
        vm.prank(address(this));
        bool ok1;
        try c.setOwner(actor) { ok1 = true; } catch { ok1 = false; }

        // step 2: the new owner sets the owner to the fuzzed target
        vm.prank(actor);
        bool ok2;
        try c.setOwner(target) { ok2 = true; } catch { ok2 = false; }

        // general rule: delegation to actor lets actor set owner to exactly the requested target
        assertTrue(ok1 && ok2 && c.owner() == target);
    }
}

